      if (b.role != null) { if (!ROLES[b.role] || b.role === "owner") return err("نقش نامعتبر است."); if (t.role === "owner") return err("نقش مدیر کل قابل تغییر نیست."); if (ROLES[b.role] >= user.level && user.role !== "owner") return err("نقش بالاتر از خودتان را نمی‌توانید بدهید.", 403); st.push(env.DB.prepare("UPDATE users SET role=? WHERE id=?").bind(b.role, id)); }
      if (b.name != null) st.push(env.DB.prepare("UPDATE users SET name=? WHERE id=?").bind(trunc(b.name, 80), id));
